<?php if (isset($_SESSION['flash'])): [$message,$type]=$_SESSION['flash']; unset($_SESSION['flash']); ?><div class="notice <?= e($type) ?>" role="status"><?= e($message) ?></div><?php endif; ?>
<?php if (!empty($error)): ?><div class="notice error" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php $workspaceFeedback=$GLOBALS['workspace_feedback'] ?? $_SESSION['workspace_feedback'] ?? null; unset($_SESSION['workspace_feedback']); if($workspaceFeedback): ?><div id="workspace-feedback" hidden data-state="<?= e($workspaceFeedback['state']) ?>" data-form-key="<?= e($workspaceFeedback['form_key']) ?>" data-errors="<?= e(json_encode($workspaceFeedback['errors'],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)) ?>" data-values="<?= e(json_encode($workspaceFeedback['values'],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)) ?>"></div><?php endif; ?>
